var order='sync';fetch('/promise-first.txt').then(function(response){order=order+'-first';return response.text();}).then(function(firstText){order=order+'-first-text';document.getElementById('first').textContent='First promise value '+firstText;return fetch('/promise-second.txt').then(function(response){return response.text();});}).then(function(secondText){order=order+'-second';document.getElementById('status').textContent=secondText;document.getElementById('status').setAttribute('style','color:#008000');return Promise.reject('expected rejection');}).catch(function(reason){order=order+'-catch-'+reason;document.getElementById('order').textContent=order;return 'Recovered';}).then(function(value){document.getElementById('recovered').textContent=value;});order=order+'-tail';
